import { Dispatch, FC, SetStateAction, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { ClockCircleOutlined } from '@ant-design/icons';

import { Button, DatePicker, Flex, Input, Select, Switch, TimePicker, Typography } from 'antd';
import dayjs from 'dayjs';
import { useFormik } from 'formik';

import EditIcon from 'assets/images/icons/edit.svg?react';
import LightningIcon from 'assets/images/icons/lightning.svg?react';
import { EditPostPageState } from 'entities/Post';
import { autoDeletionAfterDayjsValues, autoDeletionAfterOptions } from 'entities/Post/consts';
import { OPTIONS_MAX_HEIGHT_NOTIFICATIONS } from 'features/Filters';
import { AutoDeletionAfterEnum } from 'features/Planner';
import { useChannelOptions } from 'shared/hooks';
import { Content, InputClearIcon } from 'shared/ui';
import { formatDate } from 'shared/utils';

import styles from '../PostForm.module.scss';

interface IPublishingSettingsPartProps extends Pick<ReturnType<typeof useFormik>, 'setFieldValue' | 'values'> {
	editingTime: Date | null;
	setPageState: Dispatch<SetStateAction<EditPostPageState>>;
}

export const PublishingSettingsPart: FC<IPublishingSettingsPartProps> = ({
	editingTime,
	setFieldValue,
	setPageState,
	values,
}) => {
	const { t } = useTranslation();

	const { channelOptions, isFetching } = useChannelOptions();

	const [deletedTime, setDeletedTime] = useState<string>('');

	useEffect(() => {
		let deletedTime = '';
		if (values.auto_deletion_after && values.auto_deletion_after !== AutoDeletionAfterEnum.Never) {
			const publishData = values.date
				? values.date.set('hour', values.time?.hour() || 0).set('minute', values.time?.minute() || 0)
				: dayjs();
			deletedTime = publishData
				.add(
					autoDeletionAfterDayjsValues[values.auto_deletion_after as AutoDeletionAfterEnum].value,
					autoDeletionAfterDayjsValues[values.auto_deletion_after as AutoDeletionAfterEnum].unit,
				)
				.format('DD MMM, HH:mm');
		}
		setDeletedTime(deletedTime);
	}, [values.auto_deletion_after, values.date, values.time, values.publishNow]);

	const handleEditPostClick = () => {
		setPageState(EditPostPageState.POST_EDITOR);
	};

	return (
		<Content>
			<Flex vertical gap={8} className={styles.postForm}>
				<div className={styles.postForm__card}>
					<Typography.Title level={5}>{t('Канал')}</Typography.Title>
					<Select
						value={values.channel_ids}
						onChange={(value) => {
							setFieldValue('channel_ids', value);
						}}
						options={channelOptions}
						placeholder={t('Выберите канал')}
						size="large"
						showSearch
						optionFilterProp="search"
						allowClear={{ clearIcon: <InputClearIcon /> }}
						listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
						style={{ width: '100%' }}
						loading={isFetching}
						disabled={isFetching}
					/>
				</div>
				<div className={styles.postForm__card}>
					<Typography.Title level={5}>{t('Дата и время')}</Typography.Title>
					<Flex gap={8}>
						<DatePicker
							placeholder={t('Выберите дату')}
							disabled={values.publishNow}
							className={styles.postForm__fx}
							size="large"
							value={values.date}
							onChange={(value) => {
								setFieldValue('date', value);
							}}
							format="DD.MM.YYYY"
						/>
						<Input
							type="time"
							defaultValue="10:22"
							placeholder={t('Выберите время')}
							disabled={values.publishNow}
							className={styles.postForm__fx}
							size="large"
							value={values.time?.format('HH:mm')}
							onChange={(value) => {
								setFieldValue('time', dayjs(value.target.value, 'HH:mm'));
							}}
							style={{ width: '118px' }}
							suffix={<ClockCircleOutlined className={styles.clock} />}
						/>
						<TimePicker
							placeholder={t('Выберите время')}
							disabled={values.publishNow}
							className={styles.postForm__fx}
							format={'HH:mm'}
							size="large"
							value={values.time}
							onChange={(value) => {
								setFieldValue('time', value);
							}}
							inputReadOnly
							popupClassName={styles.postForm__timePickerPopup}
						/>
					</Flex>
					<label className={styles.postForm__switchBlock}>
						<LightningIcon color="#d89614" width={28} height={28} />
						<Typography.Text className={styles.postForm__w100}>{t('Опубликовать прямо сейчас')}</Typography.Text>
						<Switch
							value={values.publishNow}
							onChange={(value) => {
								setFieldValue('publishNow', value);
							}}
						/>
					</label>
					<Typography.Paragraph className={styles.postForm__label}>{t('Удалить автоматически')}</Typography.Paragraph>
					<Select
						placeholder={t('Никогда')}
						options={autoDeletionAfterOptions}
						className={styles.postForm__w100}
						size="large"
						value={values.auto_deletion_after}
						onChange={(value) => setFieldValue('auto_deletion_after', value)}
					/>
					{!!deletedTime && (
						<Typography.Paragraph type="secondary" className={styles.postForm__subText}>
							{t('Будет удалено:')} {deletedTime}
						</Typography.Paragraph>
					)}
				</div>
				<Button
					onClick={handleEditPostClick}
					htmlType="button"
					size="large"
					variant="outlined"
					color="primary"
					icon={<EditIcon />}
					disabled={!values.channel_ids}>
					{t('Редактировать пост')}
				</Button>
				{!!editingTime && (
					<Typography.Text type="secondary">
						{t('Отредактирован')}: {formatDate(editingTime, 'humanoid')}
					</Typography.Text>
				)}
			</Flex>
		</Content>
	);
};
