import { useSourcesListQuery } from 'entities/Channel';
import { SOURSCES_LIMIT } from 'features/Filters';
import { EPaginationParams } from 'features/Pagination';
import { OptionWithAvatar } from 'shared/ui';

export const useChannelOptions = () => {
	const { data, isFetching } = useSourcesListQuery({ [EPaginationParams.LIMIT]: SOURSCES_LIMIT });

	return {
		channelOptions:
			data?.results.map((channel) => ({
				search: channel.name,
				label: <OptionWithAvatar name={channel.name} logo={channel.logo_url} subText={channel.subscribers_count} />,
				value: channel.uuid,
			})) || [],
		isFetching,
	};
};
