import { BoldIcon, Code2Icon, ItalicIcon, QuoteIcon, StrikethroughIcon, UnderlineIcon } from 'lucide-react';
import { KEYS } from 'platejs';
import { useEditorReadOnly, useEditorRef } from 'platejs/react';

import { LinkToolbarButton } from './link-toolbar-button';
import { MarkToolbarButton } from './mark-toolbar-button';
import { ToolbarButton, ToolbarGroup } from './toolbar';

export function FloatingToolbarButtons() {
	const readOnly = useEditorReadOnly();
	const editor = useEditorRef();

	return (
		<>
			{!readOnly && (
				<>
					<ToolbarGroup>
						<ToolbarButton onClick={() => editor.tf.toggleBlock(KEYS.blockquote)} tooltip="Цитата">
							<QuoteIcon />
						</ToolbarButton>

						<MarkToolbarButton nodeType={KEYS.bold} tooltip="Жирный (⌘+B)">
							<BoldIcon />
						</MarkToolbarButton>

						<MarkToolbarButton nodeType={KEYS.italic} tooltip="Курсив (⌘+I)">
							<ItalicIcon />
						</MarkToolbarButton>

						<MarkToolbarButton nodeType={KEYS.underline} tooltip="Подчеркнутый (⌘+U)">
							<UnderlineIcon />
						</MarkToolbarButton>

						<MarkToolbarButton nodeType={KEYS.strikethrough} tooltip="Зачеркнутый (⌘+⇧+M)">
							<StrikethroughIcon />
						</MarkToolbarButton>

						<MarkToolbarButton nodeType={KEYS.code} tooltip="Код (⌘+E)">
							<Code2Icon />
						</MarkToolbarButton>

						<LinkToolbarButton />
					</ToolbarGroup>
				</>
			)}
		</>
	);
}
