import { useEffect, useState } from 'react';

import {
	BlockquotePlugin,
	BoldPlugin,
	CodePlugin,
	ItalicPlugin,
	StrikethroughPlugin,
	UnderlinePlugin,
} from '@platejs/basic-nodes/react';
import { BaseCodeBlockPlugin } from '@platejs/code-block';

import { EmojiKit } from '*/components/editor/plugins/emoji-kit';
import { FixedToolbarKit } from '*/components/editor/plugins/fixed-toolbar-kit';
import { FloatingToolbarKit } from '*/components/editor/plugins/floating-toolbar-kit';
import { LinkKit } from '*/components/editor/plugins/link-kit';
import { BlockquoteElement } from '*/components/ui/blockquote-node';
import { Editor, EditorContainer } from '*/components/ui/editor';
import { theme } from 'antd';
import cn from 'classnames';
import { Plate, usePlateEditor } from 'platejs/react';

interface IPlateEditorProps {
	onChange: (value: string) => void;
	htmlString: string;
}

export interface IChild {
	text: string;
	bold?: boolean;
	italic?: boolean;
	underline?: boolean;
	strikethrough?: boolean;
	code?: boolean;
	url?: string;
	children?: IChild[];
}

export interface IBlock {
	children: IChild[];
	type: string;
	id: string;
}

const formatNode = (child: IChild) => {
	let string = ``;

	if (child.bold) {
		string += `<b>`;
	}

	if (child.italic) {
		string += `<i>`;
	}

	if (child.underline) {
		string += `<u>`;
	}

	if (child.strikethrough) {
		string += `<s>`;
	}

	if (child.code) {
		string += `<code>`;
	}

	if (child.url) {
		string += `<a href="${child.url}">`;
		child.children?.forEach((child) => {
			string += formatNode(child);
		});
		string += `</a>`;
	} else {
		string += child.text;
	}

	if (child.code) {
		string += `</code>`;
	}

	if (child.strikethrough) {
		string += `</s>`;
	}

	if (child.underline) {
		string += `</u>`;
	}

	if (child.italic) {
		string += `</i>`;
	}

	if (child.bold) {
		string += `</b>`;
	}

	return string;
};

const toHtml = (value: IBlock[]) => {
	let string = ``;
	value.forEach((item, index) => {
		if (index > 0 && item.type !== 'blockquote' && value[index - 1].type !== 'blockquote') {
			string += `</br>\n`;
		}

		if (item.type === 'blockquote') {
			string += `<blockquote>`;
		}

		item.children.forEach((child) => {
			string += formatNode(child as IChild);
		});

		if (item.type === 'blockquote') {
			string += `</blockquote>`;
		}
	});

	return string;
};

export default function PlateEditor({ onChange, htmlString }: IPlateEditorProps) {
	const [v, setV] = useState('');
	const editor = usePlateEditor({
		plugins: [
			BoldPlugin,
			ItalicPlugin,
			UnderlinePlugin,
			StrikethroughPlugin,
			CodePlugin,
			BaseCodeBlockPlugin,
			BlockquotePlugin.withComponent(BlockquoteElement),
			...EmojiKit,
			...FloatingToolbarKit,
			...FixedToolbarKit,
			...LinkKit,
		], // Add the mark plugins
	});

	const {
		theme: { id },
	} = theme.useToken();

	useEffect(() => {
		const slateValue = editor.api.html.deserialize({ element: htmlString, collapseWhiteSpace: false });
		editor.tf.setValue([{ type: 'none', children: slateValue }]);
	}, []); // eslint-disable-line react-hooks/exhaustive-deps

	return (
		<Plate
			editor={editor}
			onChange={async ({ value }) => {
				console.log(toHtml(value as unknown as IBlock[]));
				onChange(toHtml(value as unknown as IBlock[]));
				setV(toHtml(value as unknown as IBlock[]));
			}}>
			<div dangerouslySetInnerHTML={{ __html: v }}></div>
			<EditorContainer className={cn(id === 1 && 'dark')}>
				<Editor placeholder="Текст поста..." />
			</EditorContainer>
		</Plate>
	);
}
