import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Select, Typography } from 'antd';

import {
	BotPostSendTimeEnum,
	useAccountSettingsPartialUpdateMutation,
	useAccountSettingsRetrieveQuery,
} from 'entities/User';
import { i18n } from 'i18n';
import { SwitchWithText } from 'shared/ui';

import styles from './SettingsNotifications.module.scss';

const sendTimeOption = [
	{ label: i18n.t('За 10 минут'), value: BotPostSendTimeEnum.$10 },
	{ label: i18n.t('За полчаса'), value: BotPostSendTimeEnum.$30 },
	{ label: i18n.t('За час'), value: BotPostSendTimeEnum.$60 },
	{ label: i18n.t('Никогда'), value: BotPostSendTimeEnum.Never },
];

interface ISettingsNotificationsProps {}

export const SettingsNotifications: FC<ISettingsNotificationsProps> = () => {
	const { t } = useTranslation();

	const { data: settings, isFetching: isSettingsFetching } = useAccountSettingsRetrieveQuery();
	const [accountSettingsPartialUpdate, { isLoading: isUpdateLoading }] = useAccountSettingsPartialUpdateMutation();

	const isLoading = isSettingsFetching || isUpdateLoading;

	return (
		<Flex vertical gap={8} className={styles.content}>
			<Typography.Title level={5} style={{ margin: 0 }}>
				{t('Уведомления')}
			</Typography.Title>
			<div className={styles.section}>
				<SwitchWithText
					subTitle={t(
						'Вы можете гибко настроить, какие уведомления хотите получать. Бот не будет удалять или размещать контент без вашего ведома. Даже при отключенной настройке вам будут приходить системные уведомление (добавление бота в канал или удаление из него).',
					)}
					onChange={(value) =>
						accountSettingsPartialUpdate(
							value
								? { bot_allow_send_digest: true }
								: {
										bot_allow_send_digest: false,
										bot_post_send_time: BotPostSendTimeEnum.Never,
										bot_notify_on_task_completion: false,
										repeat_collection_posts: false,
									},
						)
					}
					checked={!!settings?.bot_allow_send_digest}
					loading={isLoading}
					disabled={isLoading}>
					{t('Разрешить получать необязательные уведомления от бота')}
				</SwitchWithText>
			</div>

			<Flex vertical gap={8} className={styles.section}>
				<SwitchWithText
					onChange={(value) =>
						accountSettingsPartialUpdate(
							value
								? { bot_post_send_time: BotPostSendTimeEnum.$10, bot_allow_send_digest: true }
								: { bot_post_send_time: BotPostSendTimeEnum.Never },
						)
					}
					checked={!!settings?.bot_post_send_time && settings?.bot_post_send_time !== BotPostSendTimeEnum.Never}
					loading={isLoading}
					disabled={isLoading}>
					{t('Присылать пост в бота перед публикацией')}
				</SwitchWithText>

				<Select
					style={{ width: '100%' }}
					value={settings?.bot_post_send_time}
					options={sendTimeOption}
					//disabled={!settings?.bot_allow_send_digest || settings?.bot_post_send_time === BotPostSendTimeEnum.Never}
					onChange={(value) =>
						accountSettingsPartialUpdate(
							value === BotPostSendTimeEnum.Never
								? { bot_post_send_time: value }
								: { bot_post_send_time: value, bot_allow_send_digest: true },
						)
					}
					size="large"
					loading={isLoading}
					disabled={isLoading}
				/>
			</Flex>

			<div className={styles.section}>
				<SwitchWithText
					onChange={(value) =>
						accountSettingsPartialUpdate(
							value
								? { bot_notify_on_task_completion: true, bot_allow_send_digest: true }
								: { bot_notify_on_task_completion: false },
						)
					}
					checked={!!settings?.bot_notify_on_task_completion}
					loading={isLoading}
					disabled={isLoading}>
					{t('Уведомлять о выполнении заданий')}
				</SwitchWithText>
			</div>

			<div className={styles.section}>
				<SwitchWithText
					onChange={(value) =>
						accountSettingsPartialUpdate(
							value
								? { repeat_collection_posts: true, bot_allow_send_digest: true }
								: { repeat_collection_posts: false },
						)
					}
					checked={!!settings?.repeat_collection_posts}
					loading={isLoading}
					disabled={isLoading}>
					{t('Присылать статистику за прошедшие 7 дней')}
				</SwitchWithText>
			</div>
		</Flex>
	);
};
