import { FC, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Carousel, Flex, GetProp, Typography, Upload, type UploadFile, UploadProps } from 'antd';
import { useFormik } from 'formik';

import ClipIcon from 'assets/images/icons/clip.svg?react';
import DeleteIcon from 'assets/images/icons/delete.svg?react';
import { type AdvCampaignRead } from 'entities/Brand';
import { Content } from 'shared/ui';

import PlateEditor from '../../PlateEditor/PlateEditor';
import styles from '../PostForm.module.scss';

type TFileType = Parameters<GetProp<UploadProps, 'beforeUpload'>>[0];

type TPreviewFileType = TFileType & { preview: string };

const MAX_IMG_SIZE = 5 * 1024 * 1024;

const getBase64 = (file: TFileType): Promise<string> =>
	new Promise((resolve, reject) => {
		const reader = new FileReader();
		reader.readAsDataURL(file);
		reader.onload = () => resolve(reader.result as string);
		reader.onerror = (error) => reject(error);
	});

interface IPostEditorPartProps extends Pick<ReturnType<typeof useFormik>, 'setFieldValue' | 'values'> {
	advCampaign: AdvCampaignRead;
}

export const PostEditorPart: FC<IPostEditorPartProps> = ({ advCampaign, setFieldValue, values }) => {
	const { t } = useTranslation();
	const affiliateLinks = advCampaign.affiliate_links.filter((item) => values.channel_ids.includes(item.source.uuid));
	const [error, setError] = useState<string | null>(null);
	const [currentSlide, setCurrentSlide] = useState<number>();

	const handleDeleteClick = () => {
		const newFileList = values.images.concat();
		newFileList.splice(currentSlide, 1);
		setFieldValue('images', newFileList);
	};

	const handleBeforeUpload = async (file: UploadFile) => {
		setError(null);
		if (!file.url && !file.preview) {
			const isLt5M = (file.size || 0) < MAX_IMG_SIZE;
			if (!isLt5M) {
				setError(t('Изображение должно быть меньше чем 5MB'));
			} else {
				file.preview = await getBase64(file as TFileType);
			}
		}
		return false;
	};

	const onChange: UploadProps['onChange'] = ({ fileList: newFileList }) => {
		setFieldValue('images', newFileList);
	};

	const handleCarouselChange = (currentSlide: number) => {
		setCurrentSlide(currentSlide);
	};

	return (
		<Content>
			<Flex vertical gap={8}>
				<div className={styles.postForm__card}>
					<Typography.Title level={5} className={styles.postForm__m0}>
						{t('Иллюстрация')}
					</Typography.Title>

					{values.images?.length ? (
						<Carousel
							className={styles.postForm__carousel}
							afterChange={handleCarouselChange}
							dots={values.images?.length > 1}>
							{values.images.map((img: TPreviewFileType) => (
								<img key={img.uid} src={img.preview} alt={img.name} className={styles.postForm__ill} />
							))}
						</Carousel>
					) : advCampaign?.posts?.[0]?.images?.[0]?.image ? (
						<img src={advCampaign?.posts[0].images[0].image} alt="" className={styles.postForm__ill} />
					) : null}

					<Flex gap={8}>
						<Button
							onClick={handleDeleteClick}
							htmlType="button"
							size="large"
							icon={<DeleteIcon />}
							variant="outlined"
							color="danger"
							className={styles.postForm__deleteBtn}
							disabled={!values.images?.length}
						/>

						<Upload
							className={styles.postForm__upload}
							beforeUpload={handleBeforeUpload}
							onChange={onChange}
							showUploadList={false}
							fileList={values.images}
							accept={'.png, .jpg, .jpeg, .gif'}>
							<Button htmlType="button" size="large" icon={<ClipIcon />} block>
								{t('Добавить изображение')}
							</Button>
							<Typography.Text type="danger">{error}</Typography.Text>
						</Upload>
					</Flex>
				</div>
				<div className={styles.postForm__card}>
					<Typography.Title level={5}>{t('Текст поста')}</Typography.Title>
					{/*<Input.TextArea
						placeholder={`${t('Текст поста')}...`}
						value={values.content}
						onChange={(e) => {
							setFieldValue('content', e.target.value);
						}}
						className={styles.postForm__textarea}
					/>*/}
					<PlateEditor htmlString={values.content} onChange={(value) => setFieldValue('content', value)} />
				</div>
				<div className={styles.postForm__card}>
					<Typography.Title level={5}>{t('Партнерская ссылка')}</Typography.Title>
					{affiliateLinks.map((affiliateLink) => (
						<div key={affiliateLink.source.uuid}>
							<Typography.Text code underline copyable>
								{affiliateLink.affiliate_link}
							</Typography.Text>
						</div>
					))}
				</div>
			</Flex>
		</Content>
	);
};
